extern volatile char key[];
/* Icy Tower was built against an older Allegro scancode layout. */
#ifdef KEY_F1
#undef KEY_F1
#endif
#define KEY_F1 59

void build_menu_string(Tmenu *m, char *dest);

/* The original keeps the second slider bitmap in a small menu-specific
 * pointer table; it is not a Tmenu_slider despite sharing the menu data
 * field. */
void draw_menu(BITMAP *bmp, Tmenu *m, Tmenu_params *mp, int cx, int y, int dx)
{
    int pos;
    char str[256];
    int h;

    stepIn = dx;
    h = mp->font_height - 12;
    pos = -1;
    do {
        int x;

        pos++;
        x = cx + dx * pos;
        build_menu_string(m, str);
        if (m->flags & 64) {
            char key_str[32];

            key_to_str(*(int *)m->data, key_str);
            textprintf_ex(bmp, (FONT *)mp->font, x, y, -1, -1, "%s:", m->caption);
            textprintf_ex(bmp, (FONT *)mp->font, x + 101, y, -1, -1, "%s", key_str);
        }
        if (m->flags & 1)
            draw_sprite(bmp, (BITMAP *)mp->bullet,
                        x - 3 - ((BITMAP *)mp->bullet)->w, y - 3);
        textout_ex(bmp, (FONT *)mp->font, str, x, y, -1, -1);
        if (m->flags & 16) {
            DATAFILE *assets;

            assets = (DATAFILE *)mp->data + mp->fo;
            draw_sprite(bmp, (BITMAP *)assets[0].dat, x + 215, y + 10);
            draw_sprite(bmp, (BITMAP *)assets[1].dat, x + 236, y + 10);
            draw_sprite(bmp, (BITMAP *)assets[2].dat, x + 252, y + 10);
        }
        if (m->flags & 32) {
            BITMAP *b;

            b = ((BITMAP **)m->data)[2];
            draw_sprite(bmp, b, x + 244 - b->w / 2, y + h - b->h + 10);
        }
        m++;
        y += h;
    } while ((signed char)m[-1].flags >= 0);
}

void build_menu_string(Tmenu *m, char *dest)
{
    int v;
    int t;
    int i;

    if (m->flags & 2) {
        Tmenu_slider *s;
        s = (Tmenu_slider *)m->data;
        v = (s->value - s->min) / s->step;
        t = (s->max - s->min) / s->step;
        sprintf(dest, "%s: ", m->caption);
        for (i = 0; i < v; i++)
            strcat(dest, "}");
        for (; i < t; i++)
            strcat(dest, "{");
    } else if (m->flags & 8) {
        Tmenu_selection *s;
        s = (Tmenu_selection *)m->data;
        sprintf(dest, "%s: %s", m->caption, s->caption[s->value]);
    } else if (m->flags & 4) {
        int *v;
        v = (int *)m->data;
        sprintf(dest, "%s: %s", m->caption, *v ? "YES" : "NO");
    } else if (m->flags & 64) {
        char str[32];
        key_to_str(*(int *)m->data, str);
        sprintf(dest, "%s: (%s)", m->caption, str);
    } else if (m->flags & 16) {
        sprintf(dest, "%s:", m->caption);
    } else if (m->flags & 32) {
        sprintf(dest, "%s:", m->caption);
    } else
        strcpy(dest, m->caption);
}

int update_game_menu(void *bmp, Tmenu *m, Tmenu_params *mp, Tcontrol *ctrl,
                     int x, int y, int *data)
{
    int num_posts;
    int old_pos;
    int pos;
    int return_value;

    pos = 0;
    num_posts = -1;
    do {
        num_posts++;
        if (m[num_posts].flags & 1)
            pos = num_posts;
    } while ((signed char)m[num_posts].flags >= 0);
    old_pos = pos;
    draw_menu(bmp, m, mp, x, y, stepIn);
    if (ctrl) {
        if (is_up(ctrl) || is_up(&mp->ctrl)) {
            pos--;
            if (pos < 0)
                pos = num_posts;
        }
        if (is_down(ctrl) || is_down(&mp->ctrl)) {
            pos++;
            if (pos > num_posts)
                pos = 0;
        }
        if (key[KEY_F1] && pos != num_posts)
            pos = num_posts;
    }
    return_value = 0;
    if (old_pos != pos) {
        m[old_pos].flags &= ~1;
        m[pos].flags |= 1;
        play_menu_move();
    }
    if (ctrl) {
        if (is_fire(ctrl) || is_enter(&mp->ctrl) ||
            is_fire(&mp->ctrl))
            return_value = m[pos].return_select;
        if (is_left(ctrl) || is_left(&mp->ctrl))
            return_value = m[pos].return_left;
        if (is_right(ctrl) || is_right(&mp->ctrl))
            return_value = m[pos].return_right;
    }
    *data = (int)m[pos].data;
    mp->pos = pos;
    return return_value;
}

int handle_menu(Tmenu *menu, Tmenu_params *mp, Tcontrol *ctrl, BITMAP *bmp,
                void (*callback)(void), int x, int y, int dx)
{
    int menu_return;
    int handle_keys;
    int done;
    int data;
    int key_counter;

    stepIn = dx;
    data = 0;
    reset_menu(menu, mp, mp->pos);
    handle_keys = 0;
    key_counter = 0;
    menu_return = 0;
    while (!closeButtonClicked) {
        cycle_count = 0;
        checkMenuFocus();
        if (callback)
            callback();
        else
            clear(bmp);
        if (handle_keys)
            menu_return = update_game_menu(bmp, menu, mp, ctrl, x, y, &data);
        else
            menu_return = 0;
        blit_to_screen(bmp);

        if (is_any(ctrl) || is_any(&mp->ctrl) || key[KEY_F1]) {
            if (key_counter)
                key_counter--;
            else
                key_counter = 39;
            handle_keys = key_counter ? 0 : -1;
        } else {
            key_counter = 0;
            handle_keys = -1;
        }
        poll_control(ctrl, 1);
        poll_control(&mp->ctrl, 0);

        if (menu_return) {
            play_menu_select();
            switch (menu_return) {
            case 101:
            case 104:
            case 105:
            case 107:
            case 108:
            case 122:
            case 123:
            case 124:
            case 133:
                return menu_return;
            case 103: {
                int sub_ret;

                mp->pos = 0;
                sub_ret = handle_menu((Tmenu *)data, mp, ctrl, bmp, callback,
                                      x, y, dx);
                if (sub_ret && sub_ret != 108)
                    return sub_ret;
                break;
            }
            case 109: {
                Tmenu_slider *sld = (Tmenu_slider *)data;

                sld->value += sld->step;
                if (sld->value > sld->max)
                    sld->value = sld->max;
                break;
            }
            case 110: {
                Tmenu_slider *sld = (Tmenu_slider *)data;

                sld->value -= sld->step;
                if (sld->value < sld->min)
                    sld->value = sld->min;
                break;
            }
            case 111:
            case 118:
            case 120:
                if (--*(int *)data < 0)
                    *(int *)data = 0;
                break;
            case 112: {
                Tmenu_selection *sel = (Tmenu_selection *)data;

                if (++sel->value > sel->size - 1)
                    sel->value = sel->size - 1;
                break;
            }
            case 113:
                *(int *)data = *(int *)data < 1 ? -1 : 0;
                break;
            case 114: {
                int k;
                int kp;
                char txt[256];

                sprintf(txt, "press key for %s", menu[mp->pos].caption);
                line_alert(txt);
                for (k = 0; k < 128; k++)
                    key[k] = 0;
                for (;;) {
                    k = 0;
                    for (kp = 0; kp < 128; kp++)
                        if (key[kp])
                            k = kp;
                    if (k == KEY_F1)
                        k = *(int *)data;
                    rest(2);
                    if (k)
                        break;
                }
                for (kp = 0; kp < 128; kp++)
                    key[kp] = 0;
                *(int *)data = k;
                play_menu_select();
                break;
            }
            case 119:
            case 121: {
                Tmenu_floor_selection *sel = (Tmenu_floor_selection *)data;

                if (++sel->value > sel->max)
                    sel->value = sel->max;
                break;
            }
            case 131:
                view_profile(profile);
                break;
            case 132:
                change_profile();
                break;
            default: {
                char buf[256];

                sprintf(buf, "unknown return value: %d", menu_return);
                my_alert("handle_menu", buf, NULL, "OK", NULL, 0, 0);
                break;
            }
            }
        }
        while (!cycle_count)
            rest(2);
    }
    return menu_return;
}

